WITH flattened AS (SELECT id, service, log_ts, status_code, k, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS k, value) SELECT service, log_ts, status_code, k, value, ROUND(status_code / SUM(status_code) OVER (PARTITION BY k, service), 4) AS status_code_share, ROUND(status_code / SUM(status_code) OVER (PARTITION BY service), 4) AS status_code_share_2 FROM flattened WHERE k = 'trace'
